WITH base AS (SELECT * FROM order_items WHERE product_id IN (10, 15) AND unit_price IS NOT NULL AND product_id = 25), summary AS (SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, AVG(unit_price) AS avg_unit_price, COUNT(DISTINCT unit_price) AS unique_orders FROM base GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY avg_unit_price DESC
